u0646\u062d\u0648 \u0623\u0631\u062f\u0627\u0641\u0643\u060c \u0648\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0631\u0628\u0627\u0639\u064a\u062a\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629\u060c \u062b\u0645 \u0627\u062a\u0631\u0643\u0647.\n\u0643\u0631\u0631 \u0645\u0639 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1713","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["hamstrings","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1713-YUYAMEj.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1713-YUYAMEj.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"ac385e42-873e-56fe-8927-173cb912eaea","source_id":"1714","name_en":"assisted prone rectus femoris stretch","name_ar":"\u0628\u0645\u0633\u0627\u0639\u062f\u0629 \u062a\u0645\u062a\u062f \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645\u0629 \u0627\u0644\u0641\u062e\u0630\u064a\u0629 \u0627\u0644\u0645\u0639\u0631\u0636\u0629","match_names":["assisted prone rectus femoris stretch"],"muscle":"core","equipment":"assisted","aliases":["assisted prone rectus femoris stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Lie face down on the ground with your legs straight.\nBend your right knee and reach back with your right hand to grab your right foot or ankle.\nGently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh.\nHold the stretch for 20-30 seconds.\nRelease and repeat on the other side.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0648\u062c\u0647\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0633\u0627\u0642\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0629.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0627\u0631\u062c\u0639 \u0628\u064a\u062f\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0644\u0644\u0625\u0645\u0633\u0627\u0643 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0623\u0648 \u0643\u0627\u062d\u0644\u0643 \u0627\u0644\u0623\u064a\u0645\u0646.\n\u0627\u0633\u062d\u0628 \u0642\u062f\u0645\u0643 \u0623\u0648 \u0643\u0627\u062d\u0644\u0643 \u0627\u0644\u0623\u064a\u0645\u0646 \u0628\u0644\u0637\u0641 \u0646\u062d\u0648 \u0623\u0631\u062f\u0627\u0641\u0643\u060c \u0648\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0623\u0645\u0627\u0645\u064a \u0645\u0646 \u0641\u062e\u0630\u0643 \u0627\u0644\u0623\u064a\u0645\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629.\n\u062d\u0631\u0631 \u0648\u0643\u0631\u0631 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1714","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_tar