6 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0634\u0646\u0642 \u0645\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u0642\u062f\u0645\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0638\u0647\u0631\u0643 \u0648\u0627\u0633\u062d\u0628 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0627\u0644\u0645\u0642\u0627\u0628\u0636\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0633\u062d\u0628 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0630\u0642\u0646\u0643 \u0641\u0648\u0642 \u0627\u0644\u0645\u0642\u0627\u0628\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0017","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0017-kiJ4Z2K.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0017-kiJ4Z2K.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e3219821-2bd8-5c1b-8f00-35a48afba5b8","source_id":"1716","name_en":"assisted seated pectoralis major stretch with stability ball","name_ar":"\u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0639\u0636\u0644\u0629 \u0627\u0644\u0635\u062f\u0631\u064a\u0629 \u0627\u0644\u062c\u0627\u0644\u0633\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0645\u062f\u062f \u0627\u0644\u0643\u0628\u064a\u0631 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0643\u0631\u0629 \u0627\u0644\u062b\u0628\u0627\u062a","match_names":["assisted seated pectoralis major stretch with stability ball"],"muscle":"chest","equipment":"assisted","aliases":["assisted seated pectoralis major stretch with stability ball"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Sit on a stability ball with your feet flat on the ground and your back straight.\nHold a stability ball with both hands and extend your arms straight out in front of you.\nSlowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.\nHold the stretch for a few seconds, then slowly return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0629 \u062b\u0628\u0627\u062a \u0648\u0642\u062f\u0645\u0627\u0643 \u0645\u0633\u0637\u062d\u062a\u0627\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645.\n\u0623\u0645\u0633\u0643 \u0643\u0631\u0629 \u062b\u0628\u0627\u062a \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629 \u0623\u0645\u0627\u0645\u0643.\n\u0623\u0646\u0632\u0644 \u0643\u0631\u0629 \u0627\u0644\u062b\u0628\u0627\u062a \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0648\u0633\u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0639\u0636\u0644\u0627\u062a \u0635\u062f\u0631\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1716","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1716-RoV1Rfa.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1716-RoV1Rfa.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b6c587c2-f81a-55f1-836b-23228d2daee8","source_id":"1712","name_en":"assisted side lying adductor stretch","name_ar":"\u0628\u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0627\u0633\u062a\u0644\u0642\u0627\u0621 \u0627\u0644\u0639\u0636\u0644\u0629 \u0627\u0644\u0645\u0642\u0631\u0628\u0629","match_names":["assisted side lying adductor stretch"],"muscle":"adductors","equipment":"assisted","aliases":["assisted side lying adductor stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Lie on your side with your legs straight and stacked on top of each other.\nBend your bottom leg slightly for stability.\nPlace your top foot on a stable surface, such as a bench or step.\nKeeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh.\nHold the stretch for 20-30 seconds.\nReturn to the starting position and repeat on the other side.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u0643 \u0645\u0639 \u0648\u0636\u0639 \u0633\u0627\u0642\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646 \u0648\u0645\u0643\u062f\u0633\u062a\u064a\u0646 \u0641\u0648\u0642 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u062b\u0646\u064a \u0633\u0627\u0642\u0643 \u0627\u0644\u0633\u0641\u0644\u064a\u0629 \u0642\u0644\u064a\u0644\u0627\u064b \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u0627\u0633\u062a\u0642\u0631\u0627\u0631.\n\u0636\u0639 \u0642\u062f\u0645\u0643 \u0627\u0644\u0639\u0644\u064a\u0627 \u0639\u0644\u0649 \u0633\u0637\u062d \u062b\u0627\u0628\u062a\u060c \u0645\u062b\u0644 \u0627\u0644\u0645\u0642\u0639\u062f \u0623\u0648 \u0627\u0644\u062f\u0631\u062c.\n\u0623\u0628\u0642\u0650 \u0633\u0627\u0642\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u0629 \u0645\u0633\u062a\u0642\u064a\u0645\u0629\u060c \u062b\u0645 \u0627\u062e\u0641\u0636\u0647\u0627 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u062f\u0627\u062e\u0644\u064a \u0645\u0646 \u0641\u062e\u0630\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629.\n\u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0648\u0643\u0631\u0631 \u0630\u0644\u0643 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1712","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"adductors","secondary_muscles":["hamstrings","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1712-hC6oYY5.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1712-hC6oYY5.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"8aa89f4f-d875-59ca-8027-6628d66d1d43","source_id":"1758","name_en":"assisted sit-up","name_ar":"\u0645\u0633\u0627\u0639\u062f\u0629 \u0639\u0644\u0649 \u0627\u0644\u062c\u0644\u0648\u0633","match_names":["assisted sit-up"],"muscle":"core","equipment":"assisted","aliases":["assisted sit-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the edge of a bench or have someone hold your feet down.\nLie flat on your back with your knees bent and feet flat on the ground.\nPlace your hands behind your head with your elbows pointing outwards.\nEngaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\nPause for a moment at the top, then slowly lower your upper body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u0627\u0644\u0645\u0642\u0639\u062f \u0623\u0648 \u0627\u0637\u0644\u0628 \u0645\u0646 \u0634\u062e\u0635 \u0645\u0627 \u0623\u0646 \u064a\u062e\u0641\u0636 \u0642\u062f\u0645\u064a\u0643.\n\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0645\u0631\u0641\u0642\u064a\u0643 \u0644\u0644\u062e\u0627\u0631\u062c.\n\u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643\u060c \u0627\u0631\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u062b\u0645 \u0627\u0646\u062d\u0646\u064a \u0644\u0644\u0623\u0645\u0627\u0645 \u062d\u062a\u0649 \u064a\u0635\u0644 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1758","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1758-aumB2IV.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1758-aumB2IV.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"05d5dfe0-550d-5044-84f0-120d0aa474f0","source_id":"1431","name_en":"assisted standing chin-up","name_ar":"\u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0648\u0642\u0648\u0641 \u0627\u0644\u0630\u0642\u0646","match_names":["assisted standing chin-up"],"muscle":"back","equipment":"machine","aliases":["assisted standing chin-up"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the machine to your desired assistance level.\nStand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.\nKeep your chest up and shoulders back, engage your core, and slightly bend your knees.\nPull your body up by flexing your elbows and driving your elbows down towards your sides.\nContinue pulling until your chin is above the bar.\nPause for a moment at the top, then slowly lower your body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u062c\u0647\u0627\u0632 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628.\n\u0642\u0641 \u0639\u0644\u0649 \u0645\u0646\u0635\u0629 \u0627\u0644\u0642\u062f\u0645 \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u0627\u0644\u0631\u062c\u0644\u064a\u0646 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0628\u0642\u0650 \u0635\u062f\u0631\u0643 \u0645\u0631\u062a\u0641\u0639\u064b\u0627 \u0648\u0643\u062a\u0641\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641\u060c \u0648\u0627\u0634\u063a\u0644 \u062c\u0630\u0639\u0643\u060c \u0648\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627.\n\u0627\u0633\u062d\u0628 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u062f\u0641\u0639 \u0645\u0631\u0641\u0642\u064a\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0646\u062d\u0648 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0633\u062d\u0628 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0630\u0642\u0646\u0643 \u0623\u0639\u0644\u0649 \u0627\u0644\u0634\u0631\u064a\u0637.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1431","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draf