u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0645\u062a\u0628\u0627\u0639\u062f\u0629 \u0642\u0644\u064a\u0644\u0627\u064b \u0639\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0628\u0637\u0646 \u0648\u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646\u060c \u0648\u0627\u0633\u062d\u0628 \u0646\u0641\u0633\u0643 \u0646\u062d\u0648 \u0627\u0644\u0645\u0642\u0627\u0628\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0638\u0647\u0631\u0643.\n\u0623\u0646\u0632\u0644 \u0646\u0641\u0633\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1432","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1432-f4xtKBj.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1432-f4xtKBj.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"7cf679eb-3d7a-5832-860e-3bbb8db11b63","source_id":"0018","name_en":"assisted standing triceps extension (with towel)","name_ar":"\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0628\u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0648\u0642\u0648\u0641 (\u0628\u0645\u0646\u0634\u0641\u0629)","match_names":["assisted standing triceps extension (with towel)"],"muscle":"triceps","equipment":"assisted","aliases":["assisted standing triceps extension (with towel)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.\nKeep your elbows close to your ears and your upper arms stationary.\nSlowly extend your forearms upward, squeezing your triceps at the top.\nPause for a moment, then slowly lower the towel back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0627\u062d\u0645\u0644 \u0645\u0646\u0634\u0641\u0629 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643.\n\u0623\u0628\u0642\u0650 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u0623\u0630\u0646\u064a\u0643 \u0648\u0623\u0639\u0644\u0649 \u0630\u0631\u0627\u0639\u064a\u0643 \u062b\u0627\u0628\u062a\u064a\u0646.\n\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0639\u062f\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0628\u0637\u0621\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u0645\u0646\u0634\u0641\u0629 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0018","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0018-7HcfMBP.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0018-7HcfMBP.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"0e584873-f9bc-5cbe-87dc-f88a7c4120bc","source_id":"0019","name_en":"assisted triceps dip (kneeling)","name_ar":"\u0645\u0633\u0627\u0639\u062f\u0629 \u062a\u0631\u0627\u062c\u0639 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 (\u0627\u0644\u0631\u0643\u0648\u0639)","match_names":["assisted triceps dip (kneeling)"],"muscle":"triceps","equipment":"machine","aliases":["assisted triceps dip (kneeling)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the machine to your desired weight and height.\nKneel down on the pad facing the machine, with your hands gripping the handles.\nLower your body by bending your elbows, keeping your back straight and close to the machine.\nPause for a moment at the bottom, then push yourself back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629 \u0639\u0644\u0649 \u0627\u0644\u0648\u0632\u0646 \u0648\u0627\u0644\u0637\u0648\u0644 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u064a\u0646.\n\u0627\u0631\u0643\u0639 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629 \u0627\u0644\u062a\u064a \u062a\u0648\u0627\u062c\u0647 \u0627\u0644\u0622\u0644\u0629\u060c \u0645\u0639 \u0625\u0645\u0633\u0627\u0643 \u064a\u062f\u064a\u0643 \u0628\u0627\u0644\u0645\u0642\u0627\u0628\u0636.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0648\u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0648\u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u0627\u0644\u0622\u0644\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0646\u0641\u0633\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0019","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0019-J60bN17.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0019-J60bN17.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"5fa75a20-5786-55bf-8bc7-d98f099b9fa9","source_id":"2364","name_en":"assisted wide-grip chest dip (kneeling)","name_ar":"\u0645\u0633\u0627\u0639\u062f\u0629 \u0641\u064a \u062a\u0631\u0627\u062c\u0639 \u0627\u0644\u0635\u062f\u0631 \u0628\u0642\u0628\u0636\u0629 \u0648\u0627\u0633\u0639\u0629 (\u0627\u0644\u0631\u0643\u0648\u0639)","match_names":["assisted wide-grip chest dip (kneeling)"],"muscle":"chest","equipment":"machine","aliases":["assisted wide-grip chest dip (kneeling)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the machine to your desired height and secure your knees on the pad.\nGrasp the handles with a wide grip and keep your elbows slightly bent.\nLower your body by bending your elbows until your upper arms are parallel to the floor.\nPush yourself back up to the starting position by extending your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629 \u0639\u0644\u0649 \u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0648\u0642\u0645 \u0628\u062a\u062b\u0628\u064a\u062a \u0631\u0643\u0628\u062a\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u0648\u0627\u0633\u0639\u0629 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u0627\u062f\u0641\u0639 \u0646\u0641\u0633\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2364","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2364-PnZJIrk.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2364-PnZJIrk.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"5bd61c72-42b5-5fb5-8dc5-aba5c1945874","source_id":"3220","name_en":"astride jumps (male)","name_ar":"\u0642\u0641\u0632\u0627\u062a \u0645\u0646\u0641\u0631\u062c\u0629 (\u0630\u0643\u0631)","match_names":["astride jumps (male)"],"muscle":"cardio","equipment":"bodyweight","aliases":["astride jumps (male)"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart.\nBend your knees and lower your body into a squat position.\nJump explosively upwards, extending your legs and arms.\nWhile in the air, spread your legs apart and bring your arms out to the sides.\nLand softly with your feet shoulder-width apart, bending your knees to absorb the impact.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621.\n\u0627\u0642\u0641\u0632 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643.\n\u0623\u062b\u0646\u0627\u0621 \u0648\u062c\u0648\u062f\u0643 \u0641\u064a \u0627\u0644\u0647\u0648\u0627\u0621\u060c \u0642\u0645 \u0628\u0645\u0628\u0627\u0639\u062f\u0629 \u0633\u0627\u0642\u064a\u0643 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646.\n\u0627\u0647\u0628\u0637 \u0628\u0647\u062f\u0648\u0621 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0644\u0627\u0645\u062a\u0635\u0627\u0635 \u0627\u0644\u062a\u0623\u062b\u064a\u0631.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3220","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"cardio","classification_status":"needs_review","source_target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3220-f9lVSSI.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3220-f9lVSSI.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"58628a7e-1408-57ee-86ac-06451d3b9a69","source_id":"3672","name_en":"back and forth step","name_ar":"\u062e\u0637\u0648\u0629 \u0630\u0647\u0627\u0628\u0627 \u0648\u0625\u064a\u0627\u0628\u0627","match_names":["back and forth step"],"muscle":"cardio","equipment":"bodyweight","aliases":["back and forth step"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart.\nStep forward with your right foot, bending your knee and lowering your body into a lunge position.\nPush off with your right foot and step back to the starting position.\nRepeat the movement with your left foot, alternating legs with each step.\nContinue stepping back and forth, maintaining a steady pace.\nRepeat for the desired duration or number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u062a\u0642\u062f\u0645 \u0644\u0644\u0623\u0645\u0627\u0645 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649\u060c \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u0643 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u062f\u0641\u0627\u0639.\n\u0627\u062f\u0641\u0639 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631\u064a \u0627\u0644\u062d\u0631\u0643\u0629 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649\u060c \u0645\u0639 \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0645\u0639 \u0643\u0644 \u062e\u0637\u0648\u0629.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u062d\u0631\u0643 \u0630\u0647\u0627\u0628\u064b\u0627 \u0648\u0625\u064a\u0627\u0628\u064b\u0627\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0648\u062a\u064a\u0631\u0629 \u062b\u0627\u0628\u062a\u0629.\n\u0643\u0631\u0631 \u0644\u0644\u0645\u062f\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629 \u0623\u0648 \u0639\u062f\u062f \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3672","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"cardio","classification_status":"needs_review","source_target":"cardiovascular system","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3672-fNGumX0.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3672-fNGumX0.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c6c19fff-a30d-50d7-8298-32ce1db38356","source_id":"1314","name_en":"back extension on exercise ball","name_ar":"\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0638\u0647\u0631 \u0639\u0644\u0649 \u0643\u0631\u0629 \u0627\u0644\u062a\u0645\u0631\u064a\u0646","match_names":["back extension on exercise ball"],"muscle":"back","equipment":"stability_ball","aliases":["back extension on exercise ball"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.\nPosition your hands behind your head or crossed over your chest.\nEngage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.\nPause for a moment at the top, then slowly lower your upper body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0636\u0639 \u0643\u0631\u0629 \u0627\u0644\u062b\u0628\u0627\u062a \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0627\u0633\u062a\u0644\u0642\u0650 \u0641\u0648\u0642\u0647\u0627 \u0648\u0648\u062c\u0647\u0643 \u0644\u0644\u0623\u0633\u0641\u0644\u060c \u0645\u0639 \u0648\u0636\u0639 \u0648\u0631\u0643\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0643\u0631\u0629 \u0648\u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0626\u0637 \u0623\u0648 \u0623\u064a \u0633\u0637\u062d \u0645\u0633\u062a\u0642\u0631 \u0622\u062e\u0631.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0623\u0648 \u0645\u062a\u0642\u0627\u0637\u0639\u062a\u064a\u0646 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0639\u0646 \u0627\u0644\u0643\u0631\u0629\u060c \u0648\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0638\u0647\u0631\u0643 \u062d\u062a\u0649 \u064a\u0634\u0643\u0644 \u062c\u0633\u0645\u0643 \u062e\u0637\u064b\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0645\u0646 \u0631\u0623\u0633\u0643 \u0625\u0644\u0649 \u0643\u0639\u0628\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1314","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"spine","secondary_muscles":["glutes","hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1314-qLpO4vV.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1314-qLpO4vV.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"0540adfb-3b9a-59df-88a4-60027174d3f4","source_id":"3297","name_en":"back lever","name_ar":"\u0631\u0627\u0641\u0639\u0629 \u062e\u0644\u0641\u064a\u0629","match_names":["back lever"],"muscle":"back","equipment":"bodyweight","aliases":["back lever"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.\nEngage your core and pull your shoulder blades down and back.\nBend your knees and tuck them towards your chest.\nSlowly lift your legs up, keeping them straight, until your body is parallel to the ground.\nHold this position for a few seconds, then slowly lower your legs back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0646 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0642\u0644\u064a\u0644\u0627\u064b \u0639\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0633\u062d\u0628 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644 \u0648\u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0627\u062f\u0641\u0639\u0647\u0645\u0627 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643.\n\u0627\u0631\u0641\u0639\u064a \u0633\u0627\u0642\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0628\u0637\u0621\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646\u060c \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u062c\u0633\u0645\u0643 \u0645\u0648\u0627\u0632\u064a\u064b\u0627 \u0644\u0644\u0623\u0631\u0636.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3297","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","forearms","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3297-GaSzzuh.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3297-GaSzzuh.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"3ddce8df-6c3e-5817-8b73-9c5f037f5d82","source_id":"1405","name_en":"back pec stretch","name_ar":"\u062a\u0645\u062a\u062f \u0627\u0644\u0635\u062f\u0631\u064a\u0629 \u0627\u0644\u062e\u0644\u0641\u064a\u0629","match_names":["back pec stretch"],"muscle":"back","equipment":"bodyweight","aliases":["back pec stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand tall with your feet shoulder-width apart.\nExtend your arms straight out in front of you, parallel to the ground.\nCross your arms in front of your body, with your right arm over your left arm.\nInterlock your fingers and rotate your palms away from your body.\nSlowly raise your arms up and away from your body, feeling a stretch in your back and chest.\nHold the stretch for 15-30 seconds, then release.\nRepeat on the opposite side.","steps_ar":"\u0642\u0641 \u0637\u0648\u064a\u0644\u064b\u0627 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0623\u0645\u0627\u0645\u0643\u060c \u0628\u0627\u0644\u062a\u0648\u0627\u0632\u064a \u0645\u0639 \u0627\u0644\u0623\u0631\u0636.\n\u0627\u0639\u0628\u0631 \u0630\u0631\u0627\u0639\u064a\u0643 \u0623\u0645\u0627\u0645 \u062c\u0633\u0645\u0643\u060c \u0645\u0639 \u0648\u0636\u0639 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0639\u0644\u0649 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0642\u0645 \u0628\u062a\u0634\u0627\u0628\u0643 \u0623\u0635\u0627\u0628\u0639\u0643 \u0648\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u062c\u0633\u0645\u0643.\n\u0627\u0631\u0641\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0628\u0637\u0621 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u062c\u0633\u0645\u0643\u060c \u0648\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0638\u0647\u0631\u0643 \u0648\u0635\u062f\u0631\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 15-30 \u062b\u0627\u0646\u064a\u0629\u060c \u062b\u0645 \u0627\u062a\u0631\u0643\u0647.\n\u0643\u0631\u0631 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1405","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["shoulders","chest"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1405-chfnQnM.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1405-chfnQnM.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"2fb38bce-7544-5b9e-85c6-73c0ca14bbbe","source_id":"1473","name_en":"backward jump","name_ar":"\u0627\u0644\u0642\u0641\u0632 \u0625\u0644\u0649 \u0627\u0644\u0648\u0631\u0627\u0621","match_names":["backward jump"],"muscle":"quads","equipment":"bodyweight","aliases":["backward jump"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart.\nBend your knees slightly and jump backwards, pushing off with both feet.\nLand softly on the balls of your feet, bending your knees to absorb the impact.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\