645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0623\u0628\u0642\u0650 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643 \u0648\u0644\u0641 \u0630\u0631\u0627\u0639\u0643 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0643\u062a\u0641\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649.\n\u0623\u0646\u0632\u0644 \u0630\u0631\u0627\u0639\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u062b\u0645 \u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0968","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0968-3omWx6P.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0968-3omWx6P.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"dc706f0e-e831-500a-8875-bfc2850c39d7","source_id":"0969","name_en":"band alternating v-up","name_ar":"\u0627\u0644\u0641\u0631\u0642\u0629 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0639\u0644\u0649 \u0634\u0643\u0644 \u062d\u0631\u0641 V","match_names":["band alternating v-up"],"muscle":"core","equipment":"band","aliases":["band alternating v-up"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Lie flat on your back with your legs straight and your arms extended overhead, holding the band.\nEngage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.\nAs you lower your legs and upper body back down, switch the position of your legs, crossing one over the other.\nRepeat the movement, alternating the position of your legs with each repetition.\nContinue for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u0641\u0631\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062f\u0648\u062f\u062a\u064a\u0646 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643\u060c \u0645\u0645\u0633\u0643\u064a\u0646 \u0628\u0627\u0644\u0634\u0631\u064a\u0637.\n\u0642\u0645 \u0628\u0634\u062f \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643 \u0648\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0648\u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0648\u0642\u062a\u060c \u0644\u062a\u0635\u0644 \u0628\u064a\u062f\u064a\u0643 \u0646\u062d\u0648 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643.\n\u0623\u062b\u0646\u0627\u0621 \u0642\u064a\u0627\u0645\u0643 \u0628\u062e\u0641\u0636 \u0633\u0627\u0642\u064a\u0643 \u0648\u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0648\u0636\u0639 \u0633\u0627\u0642\u064a\u0643\u060c \u0628\u062d\u064a\u062b \u062a\u0639\u0628\u0631 \u0625\u062d\u062f\u0627\u0647\u0645\u0627 \u0641\u0648\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0643\u0631\u0631 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0645\u0639 \u062a\u0628\u062f\u064a\u0644 \u0648\u0636\u0639 \u0633\u0627\u0642\u064a\u0643 \u0645\u0639 \u0643\u0644 \u062a\u0643\u0631\u0627\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0969","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0969-ztAa1RK.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0969-ztAa1RK.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"45b2e465-1db1-5e9b-8a78-d58ebcd8562f","source_id":"0970","name_en":"band assisted pull-up","name_ar":"\u0627\u0644\u0641\u0631\u0642\u0629 \u0628\u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0627\u0646\u0633\u062d\u0627\u0628","match_names":["band assisted pull-up"],"muscle":"back","equipment":"band","aliases":["band assisted pull-up"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach the band to a pull-up bar or sturdy anchor point.\nStep onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart.\nHang with your arms fully extended, keeping your core engaged and your shoulders down and back.\nPull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips.\nContinue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0642\u0636\u064a\u0628 \u0627\u0644\u0633\u062d\u0628 \u0623\u0648 \u0646\u0642\u0637\u0629 \u0627\u0644\u062a\u062b\u0628\u064a\u062a \u0627\u0644\u0642\u0648\u064a\u0629.\n\u0642\u0645 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0639\u0644\u0649 \u0627\u0644\u0634\u0631\u064a\u0637 \u0648\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u0642\u0636\u064a\u0628 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0627\u062d\u0629 \u064a\u062f\u064a\u0643 \u0645\u062a\u062c\u0647\u0629 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646\u0643\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0642\u0644\u064a\u0644\u0627\u064b \u0639\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u062c\u0630\u0639\u0643 \u0645\u0646\u0634\u063a\u0644\u064b\u0627 \u0648\u0643\u062a\u0641\u064a\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u0627\u0644\u062e\u0644\u0641.\n\u0627\u0633\u062d\u0628 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0627\u0644\u0628\u0627\u0631 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627 \u0648\u062f\u0641\u0639 \u0645\u0631\u0641\u0642\u064a\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0646\u062d\u0648 \u0627\u0644\u0648\u0631\u0643\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0633\u062d\u0628 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0630\u0642\u0646\u0643 \u0623\u0639\u0644\u0649 \u0627\u0644\u0634\u0631\u064a\u0637\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0646\u0641\u0633\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0970","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0970-r1XNRYB.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0970-r1XNRYB.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"807637a5-9f3b-54fc-8833-a74c15f7d51b","source_id":"0971","name_en":"band assisted wheel rollerout","name_ar":"\u062a\u062d\u0631\u064a\u0643 \u0627\u0644\u0639\u062c\u0644\u0629 \u0628\u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0634\u0631\u064a\u0637","match_names":["band assisted wheel rollerout"],"muscle":"core","equipment":"band","aliases":["band assisted wheel rollerout"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Kneel on the floor and hold the handles of the band with both hands, palms facing down.\nPlace the band on the ground in front of you and position your hands shoulder-width apart.\nEngage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control.\nPause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0631\u0643\u0639 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0623\u0645\u0633\u0643 \u0645\u0642\u0627\u0628\u0636 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0636\u0639 \u0627\u0644\u0634\u0631\u064a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0623\u0645\u0627\u0645\u0643\u060c \u062b\u0645 \u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0645\u0633\u0627\u0641\u0629 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0643 \u0627\u0644\u0639\u062c\u0644\u0629 \u0628\u0628\u0637\u0621 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u0648\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0623\u0642\u0635\u0649 \u062d\u062f \u0645\u0645\u0643\u0646 \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u062a\u062d\u0643\u0645.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0639\u0646\u062f \u0623\u0628\u0639\u062f \u0646\u0642\u0637\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0627\u0644\u0639\u062c\u0644\u0629 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0631\u0643\u0628\u062a\u064a\u0643 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0971","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0971-zhF9lW4.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0971-zhF9lW4.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"2847ce2d-7f18-5f58-8b1f-e22e96a1c136","source_id":"1254","name_en":"band bench press","name_ar":"\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621 \u0627\u0644\u0641\u0631\u0642\u0629","match_names":["band bench press"],"muscle":"chest","equipment":"band","aliases":["band bench press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.\nGrasp the band handles with an overhand grip, slightly wider than shoulder-width apart.\nExtend your arms fully, pushing the bands away from your chest.\nSlowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u0650 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0638\u0647\u0631\u0643 \u0645\u0636\u063a\u0648\u0637\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f.\n\u0623\u0645\u0633\u0643 \u0645\u0642\u0627\u0628\u0636 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646\u0643\u0645\u0627 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0648\u0627\u062f\u0641\u0639 \u0627\u0644\u0623\u0631\u0628\u0637\u0629 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0635\u062f\u0631\u0643.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u0623\u0631\u0628\u0637\u0629 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1254","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1254-khlHMqs.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1254-khlHMqs.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"60a644c4-a3c0-5ea9-85c4-0373690c5a4f","source_id":"0980","name_en":"band bent-over hip extension","name_ar":"\u0627\u0644\u0641\u0631\u0642\u0629 \u0639\u0627\u0632\u0645\u0629 \u0639\u0644\u0649 \u0627\u0645\u062a\u062f\u0627\u062f \u0627\u0644\u0648\u0631\u0643","match_names":["band bent-over hip extension"],"muscle":"glutes","equipment":"band","aliases":["band bent-over hip extension"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach the band to a sturdy anchor point at ankle height.\nStand facing away from the anchor point with your feet shoulder-width apart.\nStep back to create tension in the band, keeping your knees slightly bent.\nHinge at the hips and lean forward, maintaining a neutral spine.\nExtend your right leg straight back, squeezing your glutes at the top.\nLower your right leg back down and repeat with the left leg.\nContinue alternating legs for the desired number of repetitions.","steps_ar":"\u0627\u0631\u0628\u0637 \u0627\u0644\u062d\u0632\u0627\u0645 \u0628\u0646\u0642\u0637\u0629 \u062a\u062b\u0628\u064a\u062a \u0642\u0648\u064a\u0629 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u0627\u062d\u0644.\n\u0642\u0641 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0646\u0642\u0637\u0629 \u0627\u0644\u062a\u062b\u0628\u064a\u062a \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0639\u062f \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0644\u062e\u0644\u0642 \u062a\u0648\u062a\u0631 \u0641\u064a \u0627\u0644\u0634\u0631\u064a\u0637\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0631\u0643\u0628\u062a\u064a\u0643 \u0645\u062b\u0646\u064a\u062a\u064a\u0646 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0627\u0644\u0645\u0641\u0635\u0644\u0629 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0627\u0646\u062d\u0646\u0627\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u0639\u0645\u0648\u062f \u0627\u0644\u0641\u0642\u0631\u064a \u0627\u0644\u0645\u062d\u0627\u064a\u062f.\n\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649.\n\u0627\u062e\u0641\u0636 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0980","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0980-wSScovH.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0980-wSScovH.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"bf6bba69-713c-5760-8f0c-d62c2fa38f5d","source_id":"0972","name_en":"band bicycle crunch","name_ar":"\u0623\u0632\u0645\u0629 \u062f\u0631\u0627\u062c\u0629 \u0627\u0644\u0641\u0631\u0642\u0629","match_names":["band bicycle crunch"],"muscle":"core","equipment":"band","aliases":["band bicycle crunch"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Lie flat on your back with your hands behind your head and your knees bent.\nLift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.\nStraighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee.\nContinue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643.\n\u0627\u0631\u0641\u0639 \u0642\u062f\u0645\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0648\u0627\u062c\u0644\u0628 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643 \u0628\u064a\u0646\u0645\u0627 \u062a\u0642\u0648\u0645 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0648\u0642\u062a \u0628\u0644\u0641 \u062c\u0630\u0639\u0643 \u0644\u062c\u0644\u0628 \u0643\u0648\u0639\u0643 \u0627\u0644\u0623\u064a\u0633\u0631 \u0646\u062d\u0648 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u0642\u0645 \u0628\u0641\u0631\u062f \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0623\u062b\u0646\u0627\u0621 \u0625\u062d\u0636\u0627\u0631 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643 \u0648\u0644\u0641 \u062c\u0630\u0639\u0643 \u0644\u062c\u0644\u0628 \u0643\u0648\u0639\u0643 \u0627\u0644\u0623\u064a\u0645\u0646 \u0646\u062d\u0648 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u062d\u0631\u0643\u0629 \u0627\u0644\u0627\u0644\u062a\u0648\u0627\u0621\u060c \u0643\u0645\u0627 \u0644\u0648 \u0643\u0646\u062a \u062a\u0642\u0648\u062f \u062f\u0631\u0627\u062c\u0629 \u0647\u0648\u0627\u0626\u064a\u0629\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0642\u0644\u0628\u0643 \u0645\u0646\u0634\u063a\u0644\u064b\u0627 \u0637\u0648\u0627\u0644 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0972","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors","obliques"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0972-tZkGYZ9.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0972-tZkGYZ9.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f91edd23-2626-54f0-82e3-b7eacb3bde78","source_id":"0974","name_en":"band close-grip pulldown","name_ar":"\u0627\u0644\u0641\u0631\u0642\u0629 \u0627\u0644\u0645\u0646\u0633\u062f\u0644\u0629 \u0642\u0628\u0636\u0629 \u0642\u0631\u064a\u0628\u0629","match_names":["band close-grip pulldown"],"muscle":"back","equipment":"band","aliases":["band close-grip pulldown"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.\nStand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart.\nStep back to create tension in the band, keeping your feet hip-width apart.\nEngage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together.\nPause for a moment at the bottom of the movement, then slowly release the band back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0631\u0628\u0637 \u0627\u0644\u062d\u0632\u0627\u0645 \u0628\u0646\u0642\u0637\u0629 \u062a\u062b\u0628\u064a\u062a \u0639\u0627\u0644\u064a\u0629\u060c \u0645\u062b\u0644 \u0634\u0631\u064a\u0637 \u0627\u0644\u0633\u062d\u0628 \u0623\u0648 \u0627\u0644\u0639\u0627\u0631\u0636\u0629 \u0627\u0644\u0642\u0648\u064a\u0629.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0646\u0642\u0637\u0629 \u0627\u0644\u062a\u062b\u0628\u064a\u062a \u0648\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0639\u062f \u0644\u0644\u062e\u0644\u0641 \u0644\u062e\u0644\u0642 \u062a\u0648\u062a\u0631 \u0641\u064a \u0627\u0644\u0634\u0631\u064a\u0637\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0642\u062f\u0645\u064a\u0643 \u0645\u062a\u0628\u0627\u0639\u062f\u062a\u064a\u0646 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0623\u062b\u0646\u0627\u0621 \u0633\u062d\u0628 \u0627\u0644\u0634\u0631\u064a\u0637 \u0644\u0623\u0633\u0641\u0644 \u0628\u0627\u062a\u062c\u0627\u0647 \u0635\u062f\u0631\u0643\u060c \u0648\u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u062d\u0631\u0651\u0631 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0628\u0637\u0621 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0974","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0974-DptumMx.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0974-DptumMx.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}}]'::jsonb)
AS r(id uuid,source_id text,name_en text,name_ar text,match_names jsonb,muscle text,equipment text,aliases jsonb,logging_mode text,load_convention text,guidance jsonb);
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM catalogue_input r WHERE (SELECT count(*) FROM public.exercises e WHERE
   (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
   OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment))>1)
 THEN RAISE EXCEPTION 'Ambiguous catalogue match; review before importing'; END IF;
END $$;
INSERT INTO public.exercises(id,name_en,name_ar,muscle,equipment,equipment_tags,aliases,logging_mode,load_convention,guidance,editorial_status)
SELECT coalesce((SELECT e.id FROM public.exercises e WHERE
  (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
  OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment)),r.id),
 r.name_en,r.name_ar,r.muscle,r.equipment,ARRAY[r.equipment],ARRAY(SELECT jsonb_array_elements_text(r.aliases)),r.logging_mode,r.load_convention,r.guidance,'needs_review'
FROM catalogue_input r
ON CONFLICT(id) DO UPDATE SET
 name_ar=coalesce(nullif(public.exercises.name_ar,''),EXCLUDED.name_ar),
 aliases=ARRAY(SELECT DISTINCT value FROM unnest(public.exercises.aliases || EXCLUDED.aliases) value ORDER BY value),
 guidance=EXCLUDED.guidance || public.exercises.guidance
WHERE public.exercises.editorial_status<>'reviewed'
 AND (public.exercises.guidance->'text_source' IS NULL OR
  (public.exercises.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND public.exercises.guidance->'text_source'->>'exercise_id'=EXCLUDED.guidance->'text_source'->>'exercise_id'));
COMMIT;
